// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/health", wrapper.HealthCheck)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/logout", wrapper.LogoutUser)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/me", wrapper.GetCurrentUser)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/openapi.yaml", wrapper.GetOpenApiYaml)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/users", wrapper.ListUsers)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/users", wrapper.CreateUser)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/users/{userId}", wrapper.GetUserById)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/users/{userId}/tokens", wrapper.ListTokens)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/users/{userId}/tokens", wrapper.CreateToken)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/api/tokens/{tokenId}", wrapper.DeleteToken)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/tokens/{tokenId}", wrapper.GetToken)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/statistics/requests", wrapper.GetRequestStatistics)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/statistics/requests/details", wrapper.GetRequestDetails)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/statistics/timeseries", wrapper.GetRequestTimeSeries)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/statistics/rate-limiter", wrapper.GetRateLimiterStats)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/config/rate-limiter", wrapper.GetRateLimiterConfig)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/middleware", wrapper.GetMiddlewareStatus)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/middleware/metrics", wrapper.GetAllMiddlewareMetrics)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/middleware/{name}/metrics", wrapper.GetMiddlewareMetrics)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/counters/{counterId}/{userId}", wrapper.GetUserCounters)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/counters/{counterId}/{userId}", wrapper.AdjustUserCounters)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/counters/{counterId}/{userId}/history", wrapper.GetUserCounterHistory)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/admin/counters", wrapper.GetAvailableCounters)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/admin/counters/{counterId}", wrapper.GetAllUserCounters)

	return m
}

